CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizar_proceso_reparacion` (IN `p_ciclo_id` INT, IN `p_paso` VARCHAR(50))   BEGIN 
    CASE p_paso 
        WHEN 'recepcion' THEN 
            UPDATE tbl_ciclos_reparacion  
            SET fecha_recepcion_taller = NOW()  
            WHERE id = p_ciclo_id; 
        WHEN 'inicio' THEN 
            UPDATE tbl_ciclos_reparacion  
            SET fecha_inicio_trabajo = NOW()  
            WHERE id = p_ciclo_id; 
        WHEN 'termino' THEN 
            UPDATE tbl_ciclos_reparacion  
            SET fecha_termino_trabajo = NOW()  
            WHERE id = p_ciclo_id; 
    END CASE; 
    SELECT ROW_COUNT() AS rows_affected; 
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizar_proceso_reparacion_molde` (IN `p_ciclo_id` INT, IN `p_paso` VARCHAR(50))   BEGIN 

  CASE p_paso 

    WHEN 'recepcion' THEN 

      UPDATE tbl_ciclos_reparacion_molde 

      SET fecha_recepcion_taller = NOW() 

      WHERE id_ciclo_reparacion = p_ciclo_id; 

    WHEN 'inicio' THEN 

      UPDATE tbl_ciclos_reparacion_molde 

      SET fecha_inicio_trabajo = NOW() 

      WHERE id_ciclo_reparacion = p_ciclo_id; 

    WHEN 'termino' THEN 

      UPDATE tbl_ciclos_reparacion_molde 

      SET fecha_termino_trabajo = NOW() 

      WHERE id_ciclo_reparacion = p_ciclo_id; 

  END CASE; 

  SELECT ROW_COUNT() AS rows_affected; 

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cerrar_ciclo_reparacion` (IN `p_ciclo_id` INT, IN `p_status_salida` VARCHAR(50), IN `p_empleado_cierre` VARCHAR(100), IN `p_comentarios` TEXT, IN `p_folio` VARCHAR(50))   BEGIN 
    UPDATE tbl_ciclos_reparacion 
    SET  
        fecha_fin_reparacion = NOW(), 
        status_salida = p_status_salida, 
        empleado_cierre = p_empleado_cierre, 
        comentarios_salida = p_comentarios, 
        folio_salida = p_folio, 
        fecha_termino_trabajo = NOW(), 
        ciclo_activo = FALSE 
    WHERE id = p_ciclo_id AND ciclo_activo = TRUE; 
    -- Also close all technician assignments 
    UPDATE tbl_tecnicos_ciclo 
    SET fecha_fin = NOW() 
    WHERE ciclo_id = p_ciclo_id AND fecha_fin IS NULL; 
    SELECT ROW_COUNT() AS rows_affected; 
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cerrar_ciclo_reparacion_molde` (IN `p_ciclo_id` INT, IN `p_status_salida` VARCHAR(50), IN `p_empleado_cierre` VARCHAR(100), IN `p_comentarios` TEXT, IN `p_folio` VARCHAR(50))   BEGIN 

  UPDATE tbl_ciclos_reparacion_molde 

  SET fecha_fin_reparacion = NOW(), 

      status_salida = p_status_salida, 

      empleado_cierre = p_empleado_cierre, 

      comentarios_salida = p_comentarios, 

      folio_salida = p_folio, 

      fecha_termino_trabajo = NOW(), 

      ciclo_activo = FALSE 

  WHERE id_ciclo_reparacion = p_ciclo_id 

    AND ciclo_activo = TRUE; 

 

  -- Also close all technician assignments 

  UPDATE tbl_tecnicos_ciclo_molde 

  SET fecha_fin = NOW() 

  WHERE ciclo_id = p_ciclo_id 

    AND fecha_fin IS NULL; 

 

  SELECT ROW_COUNT() AS rows_affected; 

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_iniciar_ciclo_reparacion` (IN `p_troquel_id` VARCHAR(20), IN `p_troquel_nombre` VARCHAR(100), IN `p_modelo` VARCHAR(100), IN `p_motivo_entrada` VARCHAR(50), IN `p_falla_id` INT, IN `p_falla_descripcion` VARCHAR(255), IN `p_folio` VARCHAR(50), IN `p_empleado` VARCHAR(100), IN `p_comentarios` TEXT, IN `p_status_anterior` VARCHAR(50), IN `p_prensa_origen` VARCHAR(50), IN `p_nivel` TINYINT, IN `p_grupo` TINYINT)   BEGIN 
    INSERT INTO tbl_ciclos_reparacion ( 
        troquel_id, 
        troquel_nombre, 
        modelo, 
        fecha_inicio_reparacion, 
        motivo_entrada, 
        falla_id, 
        falla_descripcion, 
        folio_entrada, 
        empleado_registro, 
        comentarios_entrada, 
        status_anterior, 
        prensa_origen, 
        nivel_reparacion, 
        grupo_reparacion, 
        fecha_bajado, 
        ciclo_activo 
    ) VALUES ( 
        p_troquel_id, 
        p_troquel_nombre, 
        p_modelo, 
        NOW(), 
        p_motivo_entrada, 
        p_falla_id, 
        p_falla_descripcion, 
        p_folio, 
        p_empleado, 
        p_comentarios, 
        p_status_anterior, 
        p_prensa_origen, 
        p_nivel, 
        p_grupo, 
        NOW(), 
        TRUE 
    ); 
    SELECT LAST_INSERT_ID() AS ciclo_id; 
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_iniciar_ciclo_reparacion_molde` (IN `p_molde_id` VARCHAR(50), IN `p_molde_nombre` VARCHAR(100), IN `p_modelo` VARCHAR(100), IN `p_motivo_entrada` VARCHAR(50), IN `p_falla_id` INT, IN `p_falla_descripcion` VARCHAR(255), IN `p_folio` VARCHAR(50), IN `p_empleado` VARCHAR(100), IN `p_comentarios` TEXT, IN `p_status_anterior` VARCHAR(50), IN `p_maquina_origen` VARCHAR(50), IN `p_nivel` TINYINT, IN `p_grupo` TINYINT)   BEGIN 

  INSERT INTO tbl_ciclos_reparacion_molde ( 

    molde_id, molde_nombre, modelo, 

    fecha_inicio_reparacion, motivo_entrada, 

    falla_id, falla_descripcion, 

    folio_entrada, empleado_registro, comentarios_entrada, 

    status_anterior, maquina_origen, 

    nivel_reparacion, grupo_reparacion, 

    fecha_bajado, ciclo_activo 

  ) VALUES ( 

    p_molde_id, p_molde_nombre, p_modelo, 

    NOW(), p_motivo_entrada, 

    p_falla_id, p_falla_descripcion, 

    p_folio, p_empleado, p_comentarios, 

    p_status_anterior, p_maquina_origen, 

    p_nivel, p_grupo, 

    NOW(), TRUE 

  ); 

  SELECT LAST_INSERT_ID() AS ciclo_id; 

END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_obtener_ciclo_activo` (IN `p_troquel_id` VARCHAR(20))   BEGIN 
    SELECT  
        cr.*, 
        TIMESTAMPDIFF(HOUR, cr.fecha_inicio_reparacion, NOW()) AS horas_transcurridas 
    FROM tbl_ciclos_reparacion cr 
    WHERE cr.troquel_id = p_troquel_id  
        AND cr.ciclo_activo = TRUE 
    ORDER BY cr.fecha_inicio_reparacion DESC 
    LIMIT 1; 
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_obtener_ciclo_activo_molde` (IN `p_molde_id` VARCHAR(50))   BEGIN 

  SELECT cr.*, 

    TIMESTAMPDIFF(HOUR, cr.fecha_inicio_reparacion, NOW()) AS horas_transcurridas 

  FROM tbl_ciclos_reparacion_molde cr 

  WHERE cr.molde_id = p_molde_id 

    AND cr.ciclo_activo = TRUE 

  ORDER BY cr.fecha_inicio_reparacion DESC 

  LIMIT 1; 

END$$

DELIMITER ;

